using System;using System.IO;using System.Linq;using System.Collections.Generic;using UnityEngine;using UnityEditor;using UnityEngine.SceneManagement;using Newtonsoft.Json;
public static class PerimeterFinalAudit{
 public static object ImportProvenance(){string p="Assets/Afrer_Seconds/06.Data/AssetSources/C01_Perimeter_InstrumentDetail_20261107.json";AssetDatabase.ImportAsset(p,ImportAssetOptions.ForceSynchronousImport|ImportAssetOptions.ForceUpdate);return new{path=p,guid=AssetDatabase.AssetPathToGUID(p),sceneDirty=SceneManager.GetActiveScene().isDirty};}
 public static object Run(){var scene=SceneManager.GetActiveScene();if(Application.isPlaying)throw new Exception("Saved edit scene required");var root=scene.GetRootGameObjects().Single(g=>g.name.StartsWith("B5_Circular")).transform;var player=scene.GetRootGameObjects().Single(g=>g.name.StartsWith("Player")).transform;
 var modelPaths=AssetDatabase.FindAssets("t:Model",new[]{"Assets/Afrer_Seconds/05.Model/Props/B5"}).Select(AssetDatabase.GUIDToAssetPath).Where(p=>Path.GetFileName(p).StartsWith("CP_")||Path.GetFileName(p).StartsWith("ID_")).OrderBy(p=>p).ToArray();var models=new List<object>();int badTotal=0;var missing=new List<string>();
 foreach(var p in modelPaths){var asset=AssetDatabase.LoadAssetAtPath<GameObject>(p);int bad=0,tris=0;foreach(var mf in asset.GetComponentsInChildren<MeshFilter>()){var mesh=mf.sharedMesh;var v=mesh.vertices;var t=mesh.triangles;tris+=t.Length/3;for(int i=0;i<t.Length;i+=3)if(Vector3.Cross(v[t[i+1]]-v[t[i]],v[t[i+2]]-v[t[i]]).sqrMagnitude<1e-16f)bad++;}foreach(var r in asset.GetComponentsInChildren<Renderer>())foreach(var m in r.sharedMaterials)if(!m||!m.shader||m.shader.name=="Hidden/InternalErrorShader")missing.Add(p);badTotal+=bad;models.Add(new{path=p,trianglesIncludingLODs=tris,degenerate=bad});}
 var s1=root.GetComponentsInChildren<Transform>().Single(t=>t.name=="S1_VitalMonitor_18");var repaired=s1.Find("CP_VitalMonitor_Repaired");var result=new{scene=scene.path,scene.isDirty,playerPosition=player.position.ToString("F3"),playerRotation=player.eulerAngles.ToString("F3"),modelCount=models.Count,models,badTriangles=badTotal,missingMaterials=missing,vitalLODs=repaired.GetComponent<LODGroup>().GetLODs().Select(l=>new{threshold=l.screenRelativeTransitionHeight,renderers=l.renderers.Select(r=>r?r.name:"MISSING").ToArray()}).ToArray(),activeInspectionBoxes=root.GetComponentsInChildren<Transform>().Where(t=>t.name.Contains("InspectionBox")&&Vector3.Distance(t.position,new Vector3(-15,-82,-10))<12).Select(t=>t.name).ToArray()};
 string report=Path.GetFullPath(Path.Combine(Application.dataPath,"../../../Docs/검수/2026-11-07_C01_InstrumentDetail/final_assets.json"));File.WriteAllText(report,JsonConvert.SerializeObject(result,Formatting.Indented));return new{result.modelCount,result.badTriangles,result.missingMaterials,result.playerPosition,result.playerRotation,result.vitalLODs,result.isDirty};}
}
